<script setup lang="ts">
import {onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
const props=defineProps<{id:number;active:boolean;mode:string;canEdit:boolean;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>}>();
type Outcome={preparados:number;bloqueados:number};
type Delivery={id:number;cliente_id:number;numero_registro:string;status:string;contato:string;email:string;erro:string|null;motivo:string|null;versao:string};
const confirming=ref(false),confirmed=ref(false),busy=ref(false),error=ref(''),outcome=ref<Outcome|null>(null),queue=ref(false),loading=ref(false),rows=ref<Delivery[]>([]);let alive=true,generation=0;
const labels:Record<string,string>={revisao:'Aguardando revisão',bloqueado:'Bloqueado',preparando:'Preparando',na_fila:'Na fila',enviado:'Enviado',falhou:'Falhou',cancelado:'Cancelado',enviando:'Enviando'};
function open(){confirmed.value=false;error.value='';confirming.value=true;}
async function prepare(){if(!props.canEdit||!props.active||!confirmed.value||busy.value)return;const current=generation;busy.value=true;error.value='';outcome.value=null;try{const data=await props.request<Outcome>('/api/contexto/envios/preparar','POST',{cliente_id:props.id});if(!alive||current!==generation)return;outcome.value=data;confirming.value=false;}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)busy.value=false;}}
async function loadQueue(){const current=++generation;queue.value=true;rows.value=[];error.value='';loading.value=true;try{const data=await props.request<Delivery[]>('/api/contexto/envios');if(alive&&current===generation)rows.value=data.filter(row=>row.cliente_id===props.id);}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
onBeforeUnmount(()=>{alive=false;generation++;});
</script>
<template><section class="report-actions" aria-label="Preparação de envios do cliente"><h3>Preparação de envios</h3><p>Modo do cliente: {{ mode==='automatico'?'Automático conforme regras':'Revisar antes de enviar' }}.</p><p>A preparação confere aplicabilidade, participação, contatos e tipos permitidos. Os itens preparados seguem para revisão na fila.</p><p v-if="outcome" role="status">Resultado da preparação: {{ outcome.preparados }} preparados; {{ outcome.bloqueados }} bloqueados.</p><p v-if="outcome?.preparados===0">Nenhum novo envio foi preparado nesta tentativa. Confira documentos, destinatários e itens já existentes na fila.</p><div><button v-if="canEdit" type="button" class="primary" :disabled="busy||!active" @click="open">Preparar envios do cliente</button><button type="button" class="secondary" :disabled="busy" @click="loadQueue">Abrir fila do cliente</button></div></section>
<AppDialog v-if="confirming" title="Preparar envios do cliente" :busy="busy" @close="confirming=false"><p>Preparar os documentos elegíveis deste cliente para os contatos que recebem os tipos correspondentes?</p><p>Os PDFs e originais serão preparados para revisão. Esta ação não aprova nem envia e-mails.</p><form class="vue-form" @submit.prevent="prepare"><label class="confirmation-check"><input v-model="confirmed" type="checkbox" :disabled="busy">Confirmo a preparação para este cliente.</label><p v-if="error" role="alert">{{ error }}</p><footer><button type="button" class="secondary" :disabled="busy" @click="confirming=false">Cancelar</button><button type="submit" class="primary" :disabled="busy||!confirmed">{{ busy?'Preparando…':'Confirmar preparação' }}</button></footer></form></AppDialog>
<AppDialog v-if="queue" title="Fila do cliente" @close="queue=false;generation++"><p>Consulte o resultado e os itens já preparados para este cliente. Aprovação e operação da fila pertencem à área de Envios.</p><button type="button" class="secondary" :disabled="loading" @click="loadQueue">Recarregar fila do cliente</button><p v-if="loading" role="status">Carregando fila…</p><p v-if="error" role="alert">{{ error }}</p><div v-if="!loading&&!error" class="registry-scroll"><table><caption>Envios preparados do cliente</caption><thead><tr><th scope="col">Envio e documento</th><th scope="col">Destinatário</th><th scope="col">Situação</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{ item.id }} · {{ item.numero_registro }}<details><summary>Versão do envio</summary><p class="publication-version">{{ item.versao }}</p></details></td><td>{{ item.contato }}<p>{{ item.email }}</p></td><td>{{ labels[item.status]||item.status }}<p v-if="item.erro||item.motivo">{{ item.erro||item.motivo }}</p></td></tr><tr v-if="!rows.length"><td colspan="3">Nenhum envio preparado para este cliente.</td></tr></tbody></table></div></AppDialog></template>
